def rodr(a,t):
 a=a/np.linalg.norm(a);K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]]);return np.eye(3)+np.sin(t)*K+(1-np.cos(t))*(K@K)
def fk(q,point=None,orient=False):
 R=np.eye(3);t=np.zeros(3)
 for a,pp,th in zip(axes,piv,q):
  rr=rodr(a,th);tt=pp-rr@pp;t=R@tt+t;R=R@rr
 if point is not None:return R@point+t,R
 return R
def logR(M):
 c=np.clip((np.trace(M)-1)/2,-1,1);t=np.arccos(c)
 if t<1e-8:return np.zeros(3)
 return t/(2*np.sin(t))*np.array([M[2,1]-M[1,2],M[0,2]-M[2,0],M[1,0]-M[0,1]])
p0,R0=fk(q0,ee);camR0=fk(q0)@Rc;target=np.array([.34,.035,.515]);lb=np.array([q0[0]-3.14,-2.24,q0[2]-3.14,-2.57,q0[4]-3.14,-2.09,q0[6]-3.14]);ub=np.array([q0[0]+3.14,2.24,q0[2]+3.14,2.57,q0[4]+3.14,2.09,q0[6]+3.14]);
for ow in [.0,.2,.5,1.0,2.0]:
 fun=lambda q: np.r_[20*(fk(q,ee)[0]-target),ow*logR(camR0@ (fk(q)@Rc).T),.02*(q-q0)]
 sol=least_squares(fun,q0,bounds=(lb,ub),max_nfev=1500,xtol=1e-10,ftol=1e-10,gtol=1e-10)
 pos,R=fk(sol.x,ee);ori=np.linalg.norm(logR(camR0@(fk(sol.x)@Rc).T)); print('ow',ow,'q',np.round(sol.x,3),'pos',np.round(pos,3),'e',round(np.linalg.norm(pos-target),4),'ori',round(ori,3),'dq',round(np.linalg.norm(sol.x-q0),3))
