def rot(a,t):
 a=a/np.linalg.norm(a);K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]])
 return np.eye(3)+np.sin(t)*K+(1-np.cos(t))*(K@K)
def fk(q,point=None):
 R=np.eye(3);p=np.zeros(3)
 for a,pp,th in zip(axes,piv,q):
  rr=rot(a,th);tt=pp-rr@pp;p=R@tt+p;R=R@rr
 if point is None:return R
 return R@point+p
