 th=np.arccos(np.clip((np.trace(M)-1)/2,-1,1))
 if th<1e-8:return np.zeros(3)
 return th/(2*np.sin(th))*np.array([M[2,1]-M[1,2],M[0,2]-M[2,0],M[1,0]-M[0,1]])
R0=fk(q0);cam0=R0@Rc
lb=np.array([q0[0]-3.14,-2.24,q0[2]-3.14,-2.57,q0[4]-3.14,-2.09,q0[6]-3.14]);ub=np.array([q0[0]+3.14,2.24,q0[2]+3.14,2.57,q0[4]+3.14,2.09,q0[6]+3.14])
