q=q0.copy()
for k in range(60):
 err=goal-q
 if np.linalg.norm(fk(q,ee)-target)<0.012: break
 arm=np.clip(err,-0.1,0.1)
 a=np.zeros(11);a[3:10]=arm
 res=record_live(r,a,'move scoop handle hover',cameras=['robot_wrist'],video='none')
